import{_ as t,o,c as a,a3 as d}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Bazel API","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Bazel API | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/bazel-api"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/bazel-api"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/bazel-api"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/bazel-api"}]]},"headers":[],"relativePath":"xclang/reference/bazel-api.md","filePath":"en/xclang/reference/bazel-api.md","lastUpdated":1791298549000}'),c={name:"xclang/reference/bazel-api.md"};function r(l,e,n,s,i,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="bazel-api" tabindex="-1">Bazel API <a class="header-anchor" href="#bazel-api" aria-label="Permalink to &quot;Bazel API&quot;">​</a></h1><p>Everything the <code>xclang</code> Bazel module offers. How to use it is in <a href="./../integrations/bazel">Bazel</a>; this page is the list. The module needs Bazel 9 and rules_cc 0.2.25. It is <code>packages/bazel</code> of the repository, and is published to <a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a> for every release.</p><h2 id="toolchains" tabindex="-1">Toolchains <a class="header-anchor" href="#toolchains" aria-label="Permalink to &quot;Toolchains&quot;">​</a></h2><p>The module registers, for every host, one C++ toolchain per target: <code>@xclang//bazel/toolchains:&lt;host&gt;</code> for the host itself, and <code>&lt;host&gt;-to-&lt;target&gt;</code> for the others. Each is the host archive configured for the target, and only the archive of the machine Bazel runs on is downloaded. The macOS targets have a toolchain on macOS hosts only; elsewhere, their toolchain fails the build and says why.</p><p>Every toolchain:</p><ul><li>builds Windows programs named <code>.exe</code>, and shared libraries named <code>.dll</code>;</li><li>links libraries statically into tests and programs (<a href="./../design/bazel-module#static-by-default">static by default</a>);</li><li>compiles the headers of other repositories as system headers (<code>-isystem</code>);</li><li>redacts <code>__DATE__</code>, <code>__TIME__</code> and <code>__TIMESTAMP__</code>;</li><li>puts no absolute path on a command line (<a href="./../design/bazel-module#no-absolute-paths">no absolute paths</a>).</li></ul><h2 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms&quot;">​</a></h2><p><code>@xclang//platforms:&lt;target&gt;</code>, for <code>--platforms</code>:</p><table tabindex="0"><thead><tr><th>platform</th><th>also</th><th>target</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td><code>x86_64-linux-gnu</code></td><td>Linux x64, glibc 2.17</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td><code>aarch64-linux-gnu</code></td><td>Linux arm64, glibc 2.17</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td><code>x86_64-w64-windows-gnu</code></td><td>Windows x64, MinGW-w64 (UCRT)</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td><code>aarch64-w64-windows-gnu</code></td><td>Windows arm64, MinGW-w64 (UCRT)</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td><code>arm64-apple-darwin</code></td><td>macOS arm64, from macOS hosts</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td></td><td>macOS x64, from macOS hosts</td></tr></tbody></table><p>Each has <code>@platforms//os</code>, <code>@platforms//cpu</code> and a C library, <code>@xclang//platforms/libc:glibc</code>, <code>:mingw</code> or <code>:macosx</code>. The toolchains ask a platform for os and cpu only, so a platform of one&#39;s own with those works too.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>feature</th><th>default</th><th></th></tr></thead><tbody><tr><td><code>asan</code>, <code>tsan</code>, <code>ubsan</code>, <code>lsan</code></td><td>off</td><td>sanitizers, for the whole build (<code>--features=asan</code>); <code>asan</code> compiles and links with the ASan libc++. Not for Windows targets</td></tr><tr><td><code>cpp_modules</code></td><td>off</td><td>C++20 modules: <code>module_interfaces</code> of a <code>cc_library</code>/<code>cc_binary</code>, scanned by clang-scan-deps; needs <code>--experimental_cpp_modules</code></td></tr><tr><td><code>gc_sections</code></td><td>Linux targets: on in <code>opt</code>; Windows targets: off</td><td>lld&#39;s <code>--gc-sections</code> (<a href="./../design/windows#gc-sections-and-static-initializers">why not for Windows</a>)</td></tr><tr><td><code>thinlto_cache</code></td><td>on</td><td>the linker&#39;s ThinLTO cache, with flags only when <code>XCLANG_THINLTO_CACHE</code> names a directory</td></tr><tr><td><code>generate_dsym_file</code></td><td>off</td><td>macOS targets: the link makes <code>&lt;name&gt;.dSYM</code> (output group <code>dsyms</code>); <code>--apple_generate_dsym</code> turns it on for the build</td></tr><tr><td><code>supports_dynamic_linker</code></td><td>off</td><td>Bazel&#39;s dynamic linking of libraries into tests and programs; off, they link statically</td></tr><tr><td><code>release_strip</code></td><td>on</td><td>what <code>&lt;name&gt;.stripped</code> does: <code>--strip-unneeded</code> for ELF and COFF, <code>--strip-all</code> for Mach-O (<a href="./../features/debugging#strip">strip</a>)</td></tr></tbody></table><p>A feature is turned on for a build with <code>--features=&lt;name&gt;</code>, off with <code>--features=-&lt;name&gt;</code>, and for one target with <code>features = [&quot;&lt;name&gt;&quot;]</code> or <code>[&quot;-&lt;name&gt;&quot;]</code>.</p><h2 id="targets-and-rules" tabindex="-1">Targets and Rules <a class="header-anchor" href="#targets-and-rules" aria-label="Permalink to &quot;Targets and Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>label</th><th></th></tr></thead><tbody><tr><td><code>@xclang//bazel:std</code></td><td>the <code>std</code> and <code>std.compat</code> modules of libc++, for the target platform, as a library to depend on; built with the <code>--cxxopt</code> of the build</td></tr><tr><td><code>xclang_debug_symbols(name, binary, gsymutil_args)</code> in <code>@xclang//bazel:debug_symbols.bzl</code></td><td><code>&lt;binary&gt;.gsym</code> for every target, by llvm-gsymutil with one thread (the same file each run; <code>gsymutil_args</code> come after <code>--num-threads=1</code>), and <code>&lt;binary&gt;.dSYM</code> for macOS ones (with <code>generate_dsym_file</code> on the <code>cc_binary</code>); llvm-gsymutil&#39;s output in the output group <code>gsym_log</code></td></tr><tr><td><code>@xclang//bazel:llvm-gsymutil</code></td><td>the llvm-gsymutil of the machine&#39;s toolchain, for <code>bazel run</code>: <code>bazel run @xclang//bazel:llvm-gsymutil -- &lt;absolute .gsym&gt; --address=0x&lt;address&gt;</code> (<a href="./../design/roadmap#bazel-gsymutil">unreleased</a>)</td></tr><tr><td><code>xclang_resource_dir(name, srcs)</code> in <code>@xclang//bazel:resource_dir.bzl</code></td><td>clang&#39;s resource directory laid out as <code>lib/clang/&lt;major&gt;/</code> in the rule&#39;s package, for a program <code>bin/&lt;name&gt;</code> of that package; <code>@libclang</code>&#39;s by default</td></tr></tbody></table><h2 id="repositories" tabindex="-1">Repositories <a class="header-anchor" href="#repositories" aria-label="Permalink to &quot;Repositories&quot;">​</a></h2><p>From the module extension, <code>use_extension(&quot;@xclang//bazel:extensions.bzl&quot;, &quot;xclang&quot;)</code>; each is fetched only when a build uses it.</p><table tabindex="0"><thead><tr><th>repository</th><th></th></tr></thead><tbody><tr><td><code>@libclang</code></td><td>the target platform&#39;s libclang: <code>@libclang//:clangBasic</code>, <code>:LLVMSupport</code>, ... with their link interfaces; <code>:headers</code>; <code>:resource_dir</code>; <code>:AllTargetsInfos</code>, <code>:AllTargetsDescs</code>, <code>:AllTargetsAsmParsers</code>, <code>:AllTargetsDisassemblers</code>. With <code>--features=asan</code>, the ASan build</td></tr><tr><td><code>@libclang_asan</code></td><td>the ASan build (Linux x64 and macOS arm64 targets)</td></tr><tr><td><code>@libclang_&lt;target&gt;</code></td><td>the libclang of one target</td></tr><tr><td><code>@llvm_option_inc</code></td><td>the option tables of clang, lld, llvm-lib and llvm-dlltool, as a header-only library</td></tr></tbody></table><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><p>Given with <code>--repo_env=&lt;name&gt;=&lt;value&gt;</code>:</p><table tabindex="0"><thead><tr><th>variable</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_THINLTO_CACHE</code></td><td>an absolute directory for the ThinLTO cache of the linker; the module makes it (<a href="./../features/thinlto-cache#usage">the ThinLTO cache</a>)</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>an unpacked host toolchain to use instead of the release&#39;s</td></tr><tr><td><code>XCLANG_LIBCLANG_ROOT</code>, <code>XCLANG_LIBCLANG_ASAN_ROOT</code></td><td>an unpacked host libclang, or its ASan build, to use instead of the release&#39;s</td></tr><tr><td><code>BAZEL_DO_NOT_DETECT_CPP_TOOLCHAIN=1</code></td><td>Bazel&#39;s own: turns rules_cc&#39;s detection of a local compiler off, recommended</td></tr></tbody></table><h2 id="the-release" tabindex="-1">The Release <a class="header-anchor" href="#the-release" aria-label="Permalink to &quot;The Release&quot;">​</a></h2><p><code>packages/bazel/bazel/versions.bzl</code> names the release the module downloads, and the sha256 of each of its archives, from the <code>SHA256SUMS</code> of the release. The version of the module is the release&#39;s.</p>',23)])])}const m=t(c,[["render",r]]);export{g as __pageData,m as default};
